DROP TABLE IF EXISTS `tyre_car_model_year`;
CREATE TABLE `tyre_car_model_year` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `model_id` int unsigned NOT NULL,
  `year` smallint unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_model_year` (`model_id`,`year`),
  KEY `idx_year` (`year`),
  CONSTRAINT `fk_tyre_year_model` FOREIGN KEY (`model_id`) REFERENCES `tyre_car_model` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=61344 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

